// A web page read as it comes, into a Doc (page.ts).
//
// The markup is not the page's own: the frame's runtime slimmed it on the way
// (fetch's `slim`, docs/html-slim.md), by the lists below. So there are no
// scripts, style sheets or comments here, a tag is `<name a="v" b="w">` with
// only the attributes this reads, the first `>` ends it, white space is one
// space, and a piece never ends inside a tag. What a tag MEANS is decided
// here, as Lynx and Opera Mini did it: a block, a link, a picture, a form's
// field, what is hidden, what is around the page rather than of it.
//
// An ESP32 runs this a couple of hundred times slower than a desk does, and a
// page is thousands of tags: on the path every tag and every piece of text
// takes there is no regular expression and no loop over letters, only
// indexOf, a char code at an edge and a slice of what is kept.

import { BOLD, CODE, DIM, FIELD, FOLD, H, HR, IMG, ITALIC, LI, LINK, NONE, P, PRE, ROW, SHIFT, STRUCK, add, decode, resolve, tidy,
  type Doc, type Field } from './page'

const HIDDEN_CLASS = 'hidden d-none is-hidden u-hidden hide invisible js-only print-only printonly noprint mw-editsection'
// What is around a page rather than of it, by what its markup calls it, and what this calls it.
const AROUND = 'nav navbar navigation menu sidebar footer masthead breadcrumb breadcrumbs cookie cookies consent gdpr newsletter social ' +
  'share sharing toolbar popup modal advert advertisement skip toc'
const LABELS = ['Navigation', 'Menu', 'Sidebar', 'Footer', 'Site header', 'Where this is', 'Cookie notice', 'Newsletter', 'Share', 'Tools',
  'Notice', 'Advertisement', 'Skip links', 'Contents', 'Search']
const AROUND_LABEL = [0, 0, 0, 1, 2, 3, 4, 5, 5, 6, 6, 6, 6, 7, 8, 8, 8, 9, 10, 10, 11, 11, 12, 13]

// What the runtime slims a page by (fetch's `slim`): the attributes kept (every one this asks for), the
// elements dropped with all inside them, the ones dropped when no attribute of theirs is left (they mean
// nothing by themselves), and the words of a class that stay (whole, or as a part between - and _).
export const SLIM = {
  keep: 'href src alt id class style hidden aria-hidden aria-label title name type value role width height srcset data-srcset data-src ' +
    'data-lazy-src data-original content http-equiv property rel placeholder checked selected start method action open bgcolor color text',
  drop: 'template svg math canvas object applet map noembed noframes frameset datalist',
  bare: 'span font abbr time label bdi bdo u ins mark big nobr data acronym',
  classes: HIDDEN_CLASS + ' ' + AROUND,
}

// --- what each element is ---

const KEY = 8191 // of an element on the stack: its number, and BLOCK
const BLOCK = 4096 // starts and ends a block
const WAS = 8192 // on the stack: a break was owed when it opened
const VOID = 8192 // in TAGS: has no end tag
const RAW = 16384 // its text is not markup
const SHUT = 32768 // nothing inside it is shown
const PLAIN = 65536 // nothing of its own happens where it starts: it is entered (a block breaks the text)

const TAGS = new Map<string, number>()
const ENDS: string[] = [''] // each element's end tag after its "</", by its number
let tagN = 0
// An element by its name: what it is on the stack.
const tag = (name: string, flags = 0): number => {
  TAGS.set(name, ++tagN + flags)
  ENDS.push(name + '>')
  return tagN + (flags & BLOCK)
}
// b strong, i em cite var dfn, code kbd samp tt, small sub sup, s strike del: the text inside is in a style.
for (const name of 'b strong i em cite var dfn code kbd samp tt small sub sup s strike'.split(' ')) tag(name)
const tDel = tag('del')
const STYLE_OF = [0, BOLD, BOLD, ITALIC, ITALIC, ITALIC, ITALIC, ITALIC, CODE, CODE, CODE, CODE, DIM, DIM, DIM, STRUCK, STRUCK, STRUCK]
const tA = tag('a'), tQ = tag('q'), tSelect = tag('select'), tButton = tag('button'), tPicture = tag('picture'), tOption = tag('option'),
  tFont = tag('font', PLAIN)
const tDiv = tag('div', BLOCK), tSection = tag('section', BLOCK), tP = tag('p', BLOCK + PLAIN), tArticle = tag('article', BLOCK),
  tMain = tag('main', BLOCK), tHeader = tag('header', BLOCK), tNav = tag('nav', BLOCK), tAside = tag('aside', BLOCK),
  tFooter = tag('footer', BLOCK), tH1 = tag('h1', BLOCK)
for (const name of 'h2 h3 h4 h5'.split(' ')) tag(name, BLOCK)
const tH6 = tag('h6', BLOCK), tUl = tag('ul', BLOCK), tOl = tag('ol', BLOCK), tMenu = tag('menu', BLOCK)
tag('dir', BLOCK)
const tDl = tag('dl', BLOCK)
// From here to <optgroup>: an element that ends the one of its kind before it.
const tLi = tag('li', BLOCK), tDt = tag('dt', BLOCK), tDd = tag('dd', BLOCK), tTr = tag('tr', BLOCK)
for (const name of 'thead tbody tfoot'.split(' ')) tag(name, BLOCK + PLAIN)
const tTd = tag('td', BLOCK), tTh = tag('th', BLOCK), tOptgroup = tag('optgroup', BLOCK)
const tBlockquote = tag('blockquote', BLOCK), tPre = tag('pre', BLOCK)
tag('listing', BLOCK)
tag('xmp', BLOCK)
const tPlaintext = tag('plaintext', BLOCK), tTable = tag('table', BLOCK), tCaption = tag('caption', BLOCK),
  tFigcaption = tag('figcaption', BLOCK), tForm = tag('form', BLOCK), tDetails = tag('details', BLOCK), tSummary = tag('summary', BLOCK),
  tDialog = tag('dialog', BLOCK), tBody = tag('body', BLOCK), tHtml = tag('html', BLOCK + PLAIN), tHead = tag('head', BLOCK),
  tNoscript = tag('noscript', BLOCK)
for (const name of 'fieldset legend figure address center hgroup search'.split(' ')) tag(name, BLOCK + PLAIN)
const tBr = tag('br', VOID), tHr = tag('hr', VOID), tImg = tag('img', VOID), tInput = tag('input', VOID), tMeta = tag('meta', VOID),
  tLink = tag('link', VOID), tBase = tag('base', VOID), tSource = tag('source', VOID)
for (const name of 'wbr track area col embed param'.split(' ')) tag(name, VOID)
const tTitle = tag('title', RAW), tTextarea = tag('textarea', RAW), tScript = tag('script', RAW)
tag('style', RAW)
const tIframe = tag('iframe', SHUT), tVideo = tag('video', SHUT), tAudio = tag('audio', SHUT)
for (const name of SLIM.drop.split(' ')) tag(name, SHUT) // should one come all the same
const KNOWN = tagN

const HIDDEN = new Set(HIDDEN_CLASS.split(' '))
const AROUND_AT = new Map<string, number>()
AROUND.split(' ').forEach((word, i) => AROUND_AT.set(word, AROUND_LABEL[i] + 1))
const MAIN_ID = new Set('main content main-content maincontent mw-content-text article page-content primary'.split(' '))
// A role that says what a <div> is: its label (-1: the page's own part).
const ROLES = new Map<string, number>([['main', -1], ['navigation', 0], ['contentinfo', 3], ['complementary', 2], ['banner', 4],
  ['dialog', 10], ['alertdialog', 10], ['search', 14]])
// An <input>'s type to the field it is ('': none that this fills in); any other is a line of text.
const INPUTS = new Map<string, string>([['image', 'submit'], ['submit', 'submit'], ['hidden', 'hidden'], ['checkbox', 'checkbox'],
  ['radio', 'radio'], ['password', 'password'], ['button', ''], ['reset', ''], ['file', ''], ['range', ''], ['color', '']])
const COLORS = new Map<string, string>([['black', '#000000'], ['white', '#ffffff'], ['red', '#ff0000'], ['green', '#008000'],
