// The color a value starts with (#rgb, #rrggbb, rgb(), a name this knows) as #rrggbb, or '' when it states
// none: a url(), a gradient, a variable, `transparent`, a color less than half there. `v` is in lower case.
function colorOf(v: string): string {
  v = v.trim()
  if (v.charCodeAt(0) === 35) {
    let h = (/^#[0-9a-f]{0,9}/.exec(v) as string[])[0].slice(1)
    let n = h.length
    if (n === 4 || n === 8) {
      // Its last digit (or two): how much of it is there.
      if (parseInt(h.slice(n - (n >> 2)), 16) < (n === 4 ? 8 : 128)) return ''
      n -= n >> 2
      h = h.slice(0, n)
    }
    if (n === 3) return '#' + h[0] + h[0] + h[1] + h[1] + h[2] + h[2]
    return n === 6 ? '#' + h : ''
  }
  const m = /^rgba?\(([^)]*)/.exec(v)
  if (m) {
    let rgb = 0
    let count = 0
    for (const part of m[1].split(/[\s,\/]+/)) {
      if (!part) continue
      if (count === 4) break
      // A number: its whole part and its first decimal. A percentage is of 255, or of 1 for how much of the
      // color is there (the fourth number).
      const q = /^([0-9]*)(?:\.([0-9]?)[0-9.]*)?(%?)$/.exec(part)
      if (!q || part === '%') return ''
      const whole = Math.min(parseInt(q[1] || '0', 10), 1000)
      if (count === 3) {
        if (q[3] ? whole < 50 : whole === 0 && !(q[2] && q[2] >= '5')) return ''
      } else rgb = rgb * 256 + Math.min(255, q[3] ? Math.floor((whole * 255 + 50) / 100) : whole)
