  return (name && COLORS.get(name[0])) || ''
}

// The picture of a srcset nearest 640 pixels wide.
export function pickSrcset(set: string): string {
  let best = ''
  let bestW = 0
  for (const part of set.split(/,\s+|,(?=https?:|\/)/)) {
    const m = /^\s*(\S+)(?:\s+(\d+(?:\.\d+)?)([wx]))?/.exec(part)
    if (!m) continue
    const w = m[2] ? (m[3] === 'w' ? parseFloat(m[2]) : parseFloat(m[2]) * 640) : 640
    if (!best || (bestW < 480 ? w > bestW : w >= 480 && w < bestW)) {
      best = m[1]
      bestW = w
    }
  }
  return best
}

