          }
        }
        if (to > i) text(i, to)
        rest = s.slice(to)
        break
      }
      if (lt > i) text(i, lt)
      const c = s.charCodeAt(lt + 1)
      if (c === 47) {
        // An end tag: most end the last element opened, which is told without a name to look up.
        const top = sp > 0 && !option ? ENDS[tagS[sp - 1] & 4095] : ''
        if (top && s.startsWith(top, lt + 2)) {
          i = lt + 2 + top.length
          leave()
          continue
        }
        const gt = s.indexOf('>', lt)
        const v = TAGS.get(s.slice(lt + 2, gt))
        if (v !== undefined) {
          const key = v & KEY
          if (option && (key === tOption || key === tOptgroup)) endOption()
          close(key)
        }
        i = gt + 1
        continue
      }
      if (c === 97 && hide < 0 && s.charCodeAt(lt + 2) === 32) {
        // <a href...>, the tag with attributes most seen: neither its > nor its name is looked for.
        open(tA, lt + 2, 0)
        i = tagEnd + 1
        continue
      }
      const gt = s.indexOf('>', lt)
      if (gt < 0) break // no piece ends inside a tag
      {
        // Its name ends at its > or, when it has attributes (the last of which ends in a quote), at a space.
        let from = 0
        if (s.charCodeAt(gt - 1) === 34) {
          if (space1 < lt) space1 = s.indexOf(' ', lt)
          from = space1
        }
        const name = s.slice(lt + 1, from || gt)
        let v = TAGS.get(name)
        if (v === undefined) {
          // A name of the page's own: told from the others while there are few.
          if (tagN < KNOWN + 400) {
            TAGS.set(name, (v = ++tagN + PLAIN))
            ENDS.push(name + '>')
          } else v = KEY - BLOCK + PLAIN
        }
        open(v, from, gt)
      }
      i = gt + 1
      if (d.chars + curLen > max) {
        // More than is kept: the page is cut here.
        d.cut = true
        end()
        return false
      }
    }
    if (last) {
      // What is open is closed (what was opened inside something hidden shows nothing as it goes).
      while (sp > 0) leave()
      hide = -1
      end()
    }
    return true
  }
}

