// What a page is once it is read: a Doc, a flat list of blocks (a paragraph, a
// heading, a list item, a line of a table, preformatted text, a picture, a
// form's field) with the text of each, where its links, bold and code runs
// start, and the parts of it folded away (its navigation, footer, sidebars).
//
// HTML is read by read.ts, from the markup the frame's runtime slimmed as it
// downloaded (fetch's `slim`, docs/html-slim.md). Feeds, plain text, Markdown
// and JSON are read here.

export const P = 0 // a paragraph
export const H = 1 // a heading (its level in `meta`)
export const LI = 2 // a list item (its mark in `mark`)
export const PRE = 3 // preformatted lines
export const HR = 4 // a rule
export const IMG = 5 // a picture (doc.imgs)
export const FIELD = 6 // a form's field (doc.fields)
export const FOLD = 7 // a part folded away (doc.folds)
export const ROW = 8 // a line of a table, or of a list of terms: set close to the one above
export const NONE = 9 // nothing (a fold that was not made)

// A run's style: these bits, and from LINK up the number of its link (doc.links, from 1).
export const BOLD = 1
export const ITALIC = 2
export const CODE = 4
export const DIM = 8
export const STRUCK = 16
export const LINK = 256

// A block's meta: its indent (lists), its quote depth, a gap above it, and
// from 8 bits up its heading level or the index of its picture, field or fold.
export const INDENT = 15
export const QUOTE = 16 // times the depth, up to 7
export const GAP = 128
export const SHIFT = 8

export type Img = { src: string; alt: string; w: number; h: number; link: number }
export type Field = {
  form: number
  type: string // text, password, checkbox, radio, select, submit, hidden, textarea
  name: string
  value: string
  label: string
  on?: boolean // a checkbox or radio that is ticked
  options?: string[] // a select's: value, text, value, text...
}
export type Form = { action: string; post: boolean; fields: number[] }
export type Fold = { at: number; end: number; open: boolean; label: string; links: number }
export type Doc = {
  url: string
  base: string // what its links are read against (<base href>)
  title: string
  n: number // how many blocks
  kind: number[]
  text: string[]
  // [where, style, where, style, ...]; null: one plain run. HTML's are kept as text ("0,257,11,0") until one is
  // asked for (runsOf): most of a long page is never looked at, and the text is a third of the array.
  runs: (number[] | string | null)[]
  meta: number[]
  mark: string[] // a list item's mark ("•", "3.")
  links: string[] // as the page wrote them; resolve() reads one against `base`
  imgs: Img[]
  fields: Field[]
  forms: Form[]
  folds: Fold[]
  // An id or a named anchor, and the block it is at: kept as they come (a long article has thousands, and
  // a page is asked for one or two of them), and looked up with idAt().
  idNames: string[]
  idBlocks: number[]
  feeds: string[] // the feeds the page names: url, title, url, title...
  refresh: string // <meta http-equiv="refresh">: where it sends the browser
  desc: string
  chars: number // of text kept
  cut: boolean // more came than is kept
  kindOf: string // html, text, feed, json
  max: number // text kept at most
  ld: string // its JSON-LD, for a page that shows nothing without scripts
  // The colors the page's own markup states (a bgcolor, a <font color>, a style of an element's own):
  // `palette` from 1, and for a block that has any, where each starts: [where, text color, background, ...].
  palette: string[]
  tints: Record<number, number[]>
  theme: string // <meta name="theme-color">
}


export function blank(url: string, max = 2000000): Doc {
  const d: Doc = { url, base: url, title: '', n: 0, kind: [], text: [], runs: [], meta: [], mark: [], links: [''], imgs: [],
    fields: [], forms: [], folds: [], idNames: [], idBlocks: [], feeds: [], refresh: '', desc: '', chars: 0, cut: false, kindOf: 'html', max,
    ld: '', palette: [''], tints: {}, theme: '' }
  add(d, NONE, '', null, 0) // block 0: the fold of what comes before the page's own part
  return d
}

// A block's colors, [where, text color, background, ...] (numbers of the palette, 0 for none stated), or null.
export function tintsOf(d: Doc, block: number): number[] | null {
  const t = d.tints[block]
  return t === undefined ? null : t
}

// The one background a block is on from its first letter to its last (a number of the palette), or 0.
export function bandOf(d: Doc, block: number): number {
  const t = tintsOf(d, block)
  return t && t.length === 3 && t[0] === 0 ? t[2] : 0
}

// How light a #rrggbb is, 0 to 1 (WCAG's relative luminance).
export function light(hex: string): number {
  const part = (i: number) => {
    const v = parseInt(hex.substr(i, 2), 16) / 255
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)
  }
  return 0.2126 * part(1) + 0.7152 * part(3) + 0.0722 * part(5)
}
// WCAG's contrast of two colors, 1 to 21.
export const contrast = (a: string, b: string) => {
  const x = light(a)
  const y = light(b)
  return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05)
}

// The block an id names, or -1.
export function idAt(d: Doc, id: string): number {
  const at = d.idNames.indexOf(id)
  return at < 0 ? -1 : d.idBlocks[at]
}

// A block's runs, read from how they came the first time they are asked for.
export function runsOf(d: Doc, block: number): number[] | null {
  const runs = d.runs[block]
  if (typeof runs !== 'string') return runs
  return (d.runs[block] = JSON.parse('[' + runs + ']'))
}

export function add(d: Doc, kind: number, text: string, runs: number[] | string | null, meta: number): number {
  d.kind.push(kind)
  d.text.push(text)
  d.runs.push(runs)
  d.meta.push(meta)
  d.mark.push('')
  d.chars += text.length
  return d.n++
}

// The page ended: a page that showed nothing says what it can.
export function finish(d: Doc): Doc {
  for (const f of d.folds) if (f.end < 0) f.end = d.n
  let shown = 0
  for (let i = 0; i < d.n && shown < 400; i++) if (d.kind[i] !== NONE && d.kind[i] !== FOLD) shown += d.text[i].length
  if (shown < 200 && d.kindOf === 'html') {
    // A page its scripts write: what it says of itself.
    const said = fromLd(d.ld)
    if (said || d.desc) {
      if (d.title) add(d, H, d.title, null, 1 << SHIFT)
      for (const para of (said || d.desc).split(/\n+/)) if (para.trim()) add(d, P, para.trim(), null, GAP)
    }
  }
  d.ld = ''
  return d
}

const ENTITIES = new Map<string, string>([['amp', '&'], ['lt', '<'], ['gt', '>'], ['quot', '"'], ['apos', "'"], ['nbsp', '\u00a0']])
'copy©reg®trade™hellip…mdash—ndash–lsquo‘rsquo’ldquo“rdquo”sbquo‚bdquo„laquo«raquo»lsaquo‹rsaquo›bull•middot·times×divide÷euro€pound£yen¥cent¢deg°plusmn±frac12½frac14¼frac34¾sect§para¶microµiexcl¡iquest¿szligßaacuteáeacuteéiacuteíoacuteóuacuteúyacuteýagraveàegraveèigraveìograveòugraveùacircâecircêicircîocircôucircûatildeãntildeñotildeõaumläeumlëiumlïoumlöuumlüyumlÿaringåaeligæoeligœccedilçoslashøscaronšzcaronžAacuteÁEacuteÉIacuteÍOacuteÓUacuteÚAgraveÀEgraveÈAcircÂEcircÊOcircÔAtildeÃNtildeÑOtildeÕAumlÄEumlËOumlÖUumlÜAringÅAEligÆCcedilÇOslashØScaronŠZcaronŽminus−larr←rarr→uarr↑darr↓harr↔ne≠le≤ge≥infin∞asymp≈shy\u00adensp emsp thinsp zwnj\u200czwj\u200dlrm\u200erlm\u200fprime′Prime″dagger†permil‰'
  .replace(/([A-Za-z]+[0-9]*)([^A-Za-z0-9])/g, (_, name: string, c: string) => (ENTITIES.set(name, c), ''))

const ENTITY = /&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]*);?/g
// In an attribute's value an entity needs its semicolon: `?a=1&copy=2` is an address, not a ©.
const ENTITY_WHOLE = /&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]*);/g
// Text with its character references read. `how` 1: an attribute's value; 2: text that flows (a letter that
// shows nothing is none, a line break a space).
export function decode(text: string, how = 0): string {
  let amp = text.indexOf('&')
  if (amp < 0) return text
  // One written whole (&amp; &#8212; &#x2014;), as nearly all are, is read where it stands.
  let out = ''
  let from = 0
  do {
    const end = text.indexOf(';', amp)
    if (end < 0 || end - amp > 10) return entities(text, how)
    const name = text.slice(amp + 1, end)
    let c: string | undefined
    if (name.charCodeAt(0) === 35) {
      const hex = name.charCodeAt(1) === 120
      const code = hex ? parseInt(name.slice(2), 16) : +name.slice(1)
      // A number written any other way than its own (zeros before it, a letter after) is read the long way.
      if (!(code >= 32 && code < 0xd800) || (hex ? code.toString(16) !== name.slice(2).toLowerCase() : '' + code !== name.slice(1))) return entities(text, how)
      c = String.fromCharCode(code)
    } else if ((c = ENTITIES.get(name)) === undefined) return entities(text, how)
    if (how === 2 && unseen(c.charCodeAt(0))) c = ''
    out += text.slice(from, amp) + c
    from = end + 1
    amp = text.indexOf('&', from)
  } while (amp >= 0)
  return out + text.slice(from)
}

// Whether a letter shows nothing: a soft hyphen, a zero-width space, a direction mark.
const unseen = (k: number) =>
  k === 0xad || (k >= 0x200b && k <= 0x200f) || (k >= 0x2028 && k <= 0x202e) || (k >= 0x2060 && k <= 0x2064) || k === 0xfeff

// The same of any text: an entity with no semicolon, a number out of range, a name this does not know.
function entities(text: string, how: number): string {
  return text.replace(how === 1 ? ENTITY_WHOLE : ENTITY, (all, name: string) => {
    let c: string | undefined
    if (name.charCodeAt(0) === 35) {
      const code = name.charCodeAt(1) === 120 ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      if (!(code > 0) || code > 0x10ffff || (code >= 0xd800 && code < 0xe000)) return '\ufffd'
      if (code < 32 && (how === 2 || (code !== 9 && code !== 10))) return ' '
      c = String.fromCodePoint(code)
    } else if ((c = ENTITIES.get(name)) === undefined) return all
    return how === 2 && unseen(c.charCodeAt(0)) ? '' : c
  })
}

const SPACES = /[ \t\n\r\f]+/g
// Its white space one space, none at its ends.
export const tidy = (s: string) => s.replace(SPACES, ' ').trim()

// A URL against the page's, or '' for one this browser does not open.
export function resolve(href: string, base: string): string {
  let h = href.trim()
  if (!h) return base
  if (h.indexOf('\n') >= 0 || h.indexOf('\t') >= 0) h = h.replace(/[\t\n\r]/g, '')
  const scheme = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(h)
  if (scheme) {
    const s = scheme[1].toLowerCase()
    if (s === 'http' || s === 'https') return /^https?:\/\/[^/]/i.test(h) ? h.replace(/ /g, '%20') : ''
    return s === 'mailto' || s === 'tel' || s === 'about' ? h : ''
  }
  const b = /^(https?:)\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i.exec(base)
  if (!b) return ''
  h = h.replace(/ /g, '%20')
  if (h.startsWith('//')) return b[1] + h
  if (h.charCodeAt(0) === 47) return b[1] + '//' + b[2] + dots(h)
  if (h.charCodeAt(0) === 35) return b[1] + '//' + b[2] + (b[3] || '/') + (b[4] || '') + h
  if (h.charCodeAt(0) === 63) return b[1] + '//' + b[2] + (b[3] || '/') + h
  const dir = (b[3] || '/').replace(/[^/]*$/, '')
  return b[1] + '//' + b[2] + dots(dir + h)
}

function dots(path: string): string {
  if (path.indexOf('/.') < 0) return path
  const cut = path.search(/[?#]/)
  const tail = cut < 0 ? '' : path.slice(cut)
  const out: string[] = []
  const parts = (cut < 0 ? path : path.slice(0, cut)).split('/')
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    if (part === '..') {
      if (out.length > 1) out.pop()
      if (i === parts.length - 1) out.push('')
    } else if (part === '.') {
      if (i === parts.length - 1) out.push('')
    } else out.push(part)
  }
  return (out.join('/') || '/') + tail
}

// An article's text out of the page's JSON-LD.
function fromLd(text: string): string {
  if (!text) return ''
  text = text.replace(/[\t\n\r]/g, ' ') // as written, a line break inside a string is no JSON
  const m = /"articleBody"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text) || /"description"\s*:\s*"((?:[^"\\]|\\.)*)"/.exec(text)
  if (!m) return ''
  try {
    return decode(String(JSON.parse('"' + m[1] + '"'))).slice(0, 60000)
  } catch (e) {
    return ''
  }
}

// Markup to the words in it.
export function strip(html: string): string {
  let t = html
  if (t.indexOf('<') >= 0) t = t.replace(/<(script|style)[^>]*>[^]*?<\/\1\s*>/gi, ' ').replace(/<[^>]*>/g, ' ')
  return decode(t).replace(SPACES, ' ').trim()
}

// --- feeds (RSS, Atom): each entry a heading that is its link, its date and what it says ---

const inner = (xml: string, name: string): string => {
  const m = new RegExp('<' + name + '(?:\\s[^>]*)?>([^]*?)</' + name + '\\s*>', 'i').exec(xml)
  if (!m) return ''
  const t = m[1].trim()
  const c = /^<!\[CDATA\[([^]*?)\]\]>$/.exec(t)
  return c ? c[1] : decode(t)
}

export type Feed = { d: Doc; rest: string; head: boolean }
export const feed = (d: Doc): Feed => ((d.kindOf = 'feed'), { d, rest: '', head: false })

// A piece of a feed: every entry that is whole is read, the rest waits for the next piece.
export function feedPush(f: Feed, piece: string, last: boolean): boolean {
  const d = f.d
  let s = f.rest + piece
  for (;;) {
    const m = /<(item|entry)[\s>]/i.exec(s)
    if (!m) break
    if (!f.head) {
      f.head = true
      const top = s.slice(0, m.index)
      d.title = strip(inner(top, 'title')).slice(0, 200)
      const desc = strip(inner(top, 'description') || inner(top, 'subtitle')).slice(0, 400)
      if (desc) {
        d.text[0] = desc
        d.kind[0] = P
        d.runs[0] = [0, DIM]
      }
    }
    const close = '</' + m[1]
    const end = s.toLowerCase().indexOf(close.toLowerCase(), m.index)
    if (end < 0) {
      s = s.slice(m.index)
      break
    }
    const item = s.slice(m.index, end)
    s = s.slice(end + close.length)
    let link = inner(item, 'link').trim()
    if (!link) {
      const href = /<link\b[^>]*?\bhref\s*=\s*["']([^"']+)["'][^>]*>/i.exec(item)
      if (href && !/rel\s*=\s*["'](?!alternate)/i.test(href[0])) link = decode(href[1])
    }
    let style = 0
    if (link) {
      d.links.push(link)
      style = (d.links.length - 1) * LINK
    }
    add(d, H, strip(inner(item, 'title')) || link || 'Untitled', [0, style], GAP + (3 << SHIFT))
    const date = (inner(item, 'pubDate') || inner(item, 'updated') || inner(item, 'published') || inner(item, 'dc:date')).trim()
      .replace(/^(\w{3}, \d+ \w{3} \d{4}).*$/, '$1').replace(/^(\d{4}-\d\d-\d\d)T(\d\d:\d\d).*$/, '$1 $2')
    if (date) add(d, P, date, [0, DIM], 0)
    let body = inner(item, 'content:encoded') || inner(item, 'content')
    const short = inner(item, 'description') || inner(item, 'summary')
    if (short.length > body.length || !body) body = short
    body = strip(body).slice(0, 700)
    if (body) add(d, P, body, null, 0)
    if (d.chars > d.max) {
      d.cut = true
      return false
    }
  }
  f.rest = last ? '' : s.length > 400000 ? '' : s
  return true
}

// --- what a page is, from its first bytes ---

// html, feed, text, json, or what it is that this cannot show ('pdf', 'binary', 'image').
export function sniff(head: string, type: string, url: string): string {
  const t = type.toLowerCase()
  const path = url.replace(/[?#].*$/, '').toLowerCase()
  if (/^image\//.test(t) || /\.(png|jpe?g|gif|webp|bmp)$/.test(path)) return 'image'
  if (t.indexOf('pdf') >= 0 || head.startsWith('%PDF')) return 'pdf'
  const start = head.slice(0, 1024).trimStart()
  const lower = start.slice(0, 600).toLowerCase()
  if (/<(rss|feed|rdf:rdf)[\s>]/.test(lower)) return 'feed'
  if (t.indexOf('html') >= 0) return 'html'
  if (t.indexOf('json') >= 0) return 'json'
  if (t.indexOf('text/plain') >= 0) return /\.(md|markdown)$/.test(path) ? 'markdown' : 'text'
  if (/^(audio|video|font)\/|octet-stream|zip|gzip|tar|msword|officedocument/.test(t)) return 'binary'
  if (/[\x00-\x08\x0e-\x1f]/.test(start.slice(0, 400))) return 'binary'
  if (lower.startsWith('<!doctype html') || /<(html|head|body|title|div|p|table|h1|a|meta|script)[\s>]/.test(lower)) return 'html'
  if (t.indexOf('xml') >= 0 && /<(rss|feed|rdf:rdf|channel)[\s>]/.test(head.slice(0, 4096).toLowerCase())) return 'feed'
  if ((start.charCodeAt(0) === 123 || start.charCodeAt(0) === 91) && /^[\[{]\s*("|\{|\[|\d|\]|\}|t|f|n)/.test(start)) return 'json'
  if (/\.(md|markdown)$/.test(path)) return 'markdown'
  return 'text'
}

// --- text that is not markup ---

export type Plain = { d: Doc; rest: string; para: string; pre: string[]; md: boolean; fence: boolean }

export function plain(d: Doc, markdown: boolean): Plain {
  d.kindOf = markdown ? 'markdown' : 'text'
  return { d, rest: '', para: '', pre: [], md: markdown, fence: false }
}

// A piece of plain text: lines that read on are a paragraph, lines laid out by
// hand (indented, columns of spaces, drawn boxes) stay as they are.
export function plainPush(p: Plain, piece: string, last: boolean): boolean {
  const r = p.d
  const s = p.rest + piece.replace(/\r\n?/g, '\n').replace(/\x1b\[[0-9;]*[A-Za-z]/g, '')
  let i = 0
  for (;;) {
    const nl = s.indexOf('\n', i)
    if (nl < 0) break
    plainLine(p, s.slice(i, nl))
    i = nl + 1
    if (r.chars > r.max) {
      r.cut = true
      return false
    }
  }
  p.rest = s.slice(i)
  if (last) {
    if (p.rest) plainLine(p, p.rest)
    p.rest = ''
    plainLine(p, '')
  }
  return true
}

const LAID = /^\s{2,}\S|\S\s{3,}\S|^\s*[|+\-=_*#~.]{4,}\s*$|\t|^\s*[|+].*[|+]\s*$/

function plainLine(p: Plain, line: string) {
  const r = p.d
  const endPara = () => {
    if (p.para) {
      if (p.md) mdBlock(r, p.para)
      else add(r, P, p.para.replace(/\n+$/, ''), null, GAP)
      p.para = ''
    }
  }
  const endPre = () => {
    if (p.pre.length) {
      while (p.pre.length && !p.pre[p.pre.length - 1].trim()) p.pre.pop()
      if (p.pre.length) add(r, PRE, p.pre.join('\n'), null, GAP)
      p.pre = []
    }
  }
  if (p.md && /^\s*(```|~~~)/.test(line)) {
    endPara()
    if (p.fence) endPre()
    p.fence = !p.fence
    return
  }
  if (p.fence) {
    p.pre.push(line)
    return
  }
  if (!line.trim()) {
    endPara()
    if (p.pre.length) p.pre.push('')
    return
  }
  if (p.md) {
    // A heading, a rule, a list item or a quote is a block of its own.
    if (/^\s{0,3}(#{1,6}\s|[-*+]\s|\d+[.)]\s|>|[-*_]{3,}\s*$|\|)/.test(line)) {
      endPara()
      endPre()
      mdBlock(r, line)
      return
    }
    if (/^(\s{4,}|\t)/.test(line) && !p.para) {
      p.pre.push(line.replace(/^(\s{4}|\t)/, ''))
      return
    }
    endPre()
    p.para += (p.para ? ' ' : '') + line.trim()
    return
  }
  if (LAID.test(line) && !/^\s{2,8}\S.{40,}$/.test(line)) {
    endPara()
    p.pre.push(line.replace(/\t/g, '    '))
    return
  }
  if (p.pre.length && p.pre[p.pre.length - 1] !== '' && line.length < 40 && !p.para) {
    p.pre.push(line) // a short line among laid out ones is one of them
    return
  }
  endPre()
  const t = line.trim()
  // A short line ends its paragraph (an address, a verse, a heading).
  if (p.para && p.para.length - p.para.lastIndexOf('\n') - 1 < 46 && p.para.indexOf('\n') < 0 && p.para.length < 46) p.para += '\n' + t
  else p.para += (p.para ? (p.para.endsWith('\n') ? '' : ' ') : '') + t
  if (t.length < 46) p.para += '\n'
}

const MD_INLINE = /(\*\*|__)(?=\S)(.+?)\1|(`+)(.+?)\3|!?\[([^\]]*)\]\(([^)\s]+)(?:\s+"[^"]*")?\)|(\*|_)(?=\S)([^*_]+?)\7|<((?:https?:\/\/)[^>\s]+)>/g

// A block of Markdown: what it is by how it starts, and the links, bold and code in its line.
function mdBlock(r: Doc, text: string) {
  const d = r
  let kind = P
  let meta = GAP
  let markText = ''
  let m: RegExpExecArray | null
  let t = text
  if ((m = /^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/.exec(t))) {
    kind = H
    meta = GAP + (m[1].length << SHIFT)
    t = m[2]
  } else if (/^\s{0,3}([-*_])(\s*\1){2,}\s*$/.test(t)) {
    add(r, HR, '', null, 0)
    return
  } else if ((m = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(t))) {
    kind = LI
    meta = Math.min(15, 1 + (m[1].length >> 1))
    markText = m[2].length > 1 ? m[2].replace(')', '.') : '\u2022'
    t = m[3].replace(/^\[( |x)\]\s/i, (_, x: string) => (x === ' ' ? '[ ] ' : '[x] '))
  } else if ((m = /^\s{0,3}((?:>\s?)+)(.*)$/.exec(t))) {
    meta = GAP + QUOTE * Math.min(7, m[1].replace(/\s/g, '').length)
    t = m[2]
  } else if (/^\s*\|/.test(t)) {
    if (/^\s*\|?[\s:|-]+\|?\s*$/.test(t)) return
    kind = ROW
    meta = 0
    t = t.trim().replace(/^\||\|$/g, '').split('|').map((c) => c.trim()).join('  |  ')
  }
  let out = ''
  const runs: number[] = [0, kind === H ? 0 : 0]
  let at = 0
  MD_INLINE.lastIndex = 0
  while ((m = MD_INLINE.exec(t))) {
    out += t.slice(at, m.index)
    at = m.index + m[0].length
    let style = 0
    let body = ''
    if (m[2] !== undefined) { style = BOLD; body = m[2] }
    else if (m[4] !== undefined) { style = CODE; body = m[4] }
    else if (m[6] !== undefined) {
      if (m[0].charCodeAt(0) === 33 && !m[5]) continue
      d.links.push(m[6])
      style = (d.links.length - 1) * LINK
      body = m[5] || m[6]
    } else if (m[8] !== undefined) { style = ITALIC; body = m[8] }
    else if (m[9] !== undefined) {
      d.links.push(m[9])
      style = (d.links.length - 1) * LINK
      body = m[9]
    }
    runs.push(out.length, style)
    out += body
    runs.push(out.length, 0)
  }
  out += t.slice(at)
  if (!out.trim()) return
  const i = add(r, kind, out, runs.length > 2 ? runs : null, meta)
  if (markText) d.mark[i] = markText
}

// JSON, set out a value a line.
export function jsonDoc(r: Doc, text: string) {
  r.kindOf = 'json'
  let shown = text
  try {
    shown = JSON.stringify(JSON.parse(text), null, 2)
  } catch (e) {
    // as it came
  }
  add(r, PRE, shown.slice(0, r.max), null, 0)
}

