// A Doc (page.ts) set in lines for a width, a block at a time and only as far
// down as has been asked for: rows(), then reach() to a height.
//
// A row is one line of text of a block (from one character to another), or a
// picture, a field, a rule or the line of a fold. Where each row is and how
// tall are numbers in flat arrays, so a page of ten thousand lines is a few
// hundred KB and drawing it is drawing the rows around where it is scrolled
// to. Lines are broken here, with the width of each letter of the frame's
// face (Ubuntu) from a table, since a row is drawn as one line that does not
// wrap: the page is as tall as its rows say before anything is drawn.

import { BOLD, FIELD, FOLD, GAP, H, HR, IMG, INDENT, LI, NONE, PRE, ROW, SHIFT, runsOf, type Doc } from './page'

// Ubuntu Regular's advance widths, in 1/1000 em: U+0020..U+007E, then U+00A0..U+017F, two base-36 digits a letter.
const ASCII = '6f7obmijfonuii6p9090dcfo6u8b6uaofofofofofofofofofofo6u6ufofofob8qeifhvh8jtfvexiojl7hdwhhefo7k8lmgwlmhhesfpj4i8pthjgmfx95ao95fodoageigdcxgdfjaqg2fv7171ei7lnxfygegdgdaqceb6fydylle7dtd3997r99fo'
const LATIN = ''
const CW = new Uint16Array(0x180)
CW.fill(560)
for (let i = 0; i * 2 < ASCII.length; i++) CW[32 + i] = parseInt(ASCII.substr(i * 2, 2), 36)
for (let i = 0; i * 2 < LATIN.length; i++) CW[160 + i] = parseInt(LATIN.substr(i * 2, 2), 36)

// A letter past the table: punctuation by name, wide scripts a full em.
function wide(c: number): number {
  if (c < 0x2000) return c >= 0x370 && c < 0x530 ? 600 : 560
  if (c < 0x2070) return c === 0x2014 || c === 0x2026 ? 996 : c === 0x2013 ? 496 : c === 0x2018 || c === 0x2019 ? 235 : c === 0x2022 ? 360 : 420
  if (c >= 0xd800 && c < 0xdc00) return 1000 // half of a pair: the pair is one wide letter
  if (c >= 0xdc00 && c < 0xe000) return 0
  if (c >= 0x2e80 && c < 0xa000) return 1000
  if (c >= 0xac00 && c < 0xd7b0) return 1000
  if (c >= 0xff00 && c < 0xff61) return 1000
  return 620
}

// How wide `text` from `a` to `b` is at 1000 pixels a letter's em.
export function widthOf(text: string, a: number, b: number): number {
  let w = 0
  for (let i = a; i < b; i++) {
    const c = text.charCodeAt(i)
    w += c < 0x180 ? CW[c] : wide(c)
  }
  return w
}

export type Look = {
  width: number // the page's, in pixels
  px: number // the text's size
  pics: boolean // pictures are drawn
  tall: number // a picture's height at most
  jpegs?: boolean // only the kinds a small frame decodes (an ESP32: no WebP)
}

// Whether a picture is drawn, or stands as its words.
export const drawn = (src: string, look: Look) => look.pics && !(look.jpegs && /\.(webp|avif)([?#]|$)/i.test(src))

export type Rows = {
  doc: Doc
  look: Look
  n: number
  block: number[]
  from: number[] // a text row: its first character
  to: number[] // and one past its last
  y: number[] // where its top is
  h: number[]
  next: number // the block to set next
  bottom: number // where the next row goes
  seen: number // characters of the blocks set so far
}

export function rows(doc: Doc, look: Look): Rows {
  return { doc, look, n: 0, block: [], from: [], to: [], y: [], h: [], next: 0, bottom: Math.round(look.px * 0.5), seen: 0 }
}

// A block's text size, as a share of the page's, and its line height.
export const scaleOf = (kind: number, meta: number) =>
  kind === H ? (meta >> SHIFT === 1 ? 1.5 : meta >> SHIFT === 2 ? 1.3 : meta >> SHIFT === 3 ? 1.15 : 1) : kind === PRE ? 0.88 : 1
export const lineOf = (px: number) => Math.round(px * 1.36)
export const indentOf = (meta: number, px: number) => Math.round(((meta & INDENT) * 1.3 + ((meta >> 4) & 7) * 0.9) * px)
export const PAD = 0.5 // of the text's size, at each side of the page

function put(r: Rows, block: number, from: number, to: number, h: number) {
  r.block.push(block)
  r.from.push(from)
  r.to.push(to)
  r.y.push(r.bottom)
  r.h.push(h)
  r.bottom += h
  r.n++
}

// A picture's box: as wide as the page lets it, as tall as its shape says, its link's tap its own.
export function pictureBox(w: number, h: number, room: number, tall: number): [number, number] {
  let bw = w > 0 ? Math.min(room, Math.max(w, Math.min(room, 240))) : room
  let bh = w > 0 && h > 0 ? Math.round((bw * h) / w) : Math.round(bw * 0.5625)
  if (bh > tall) {
    if (w > 0 && h > 0) bw = Math.round((tall * w) / h)
    bh = tall
  }
  return [Math.max(16, bw), Math.max(16, bh)]
}

// Sets blocks in rows until the rows reach `y` (or the page ends). True when rows were added.
export function reach(r: Rows, y: number): boolean {
  const d = r.doc
  const px = r.look.px
  const before = r.n
  while (r.next < d.n && r.bottom <= y) {
    const i = r.next++
    const kind = d.kind[i]
    if (kind === NONE) continue
    r.seen += d.text[i].length
    const meta = d.meta[i]
    const size = Math.round(px * scaleOf(kind, meta))
    const line = lineOf(size)
    const room = Math.max(60, r.look.width - 2 * Math.round(px * PAD) - indentOf(meta, px))
    // The space above: a gap asked for, a heading's, a paragraph's; a list item or a table's line sits close.
    const gap = kind === H ? 0.7 : meta & GAP ? 0.55 : kind === LI ? 0.18 : kind === ROW ? 0.12 : 0.4
    if (r.n) r.bottom += Math.round(px * gap)
    if (kind === FOLD) {
      const f = d.folds[meta >> SHIFT]
      put(r, i, 0, 0, Math.round(px * 1.9))
      if (!f.open && f.end > r.next) {
        for (let k = r.next; k < f.end; k++) r.seen += d.text[k].length
        r.next = f.end
      }
      continue
    }
    if (kind === HR) {
      put(r, i, 0, 0, Math.round(px * 0.6))
      continue
    }
    if (kind === IMG) {
      const g = d.imgs[meta >> SHIFT]
      if (!drawn(g.src, r.look)) put(r, i, 0, 0, line)
      else put(r, i, 0, 0, pictureBox(g.w, g.h, room, r.look.tall)[1] + Math.round(px * 0.2))
      continue
    }
    if (kind === FIELD) {
      const f = d.fields[meta >> SHIFT]
      put(r, i, 0, 0, f.type === 'checkbox' || f.type === 'radio' ? line : Math.round(px * 2.3))
      continue
    }
    const text = d.text[i]
    const runs = runsOf(d, i)
    // The width left, in 1/1000 em of this block's size; a hair kept back for
    // what the table does not know (kerning, a bold face a little wider).
    const max = ((room - 2) * 1000) / size
    const n = text.length
    let start = 0
    let x = 0
    let brk = -1 // where the line can break: after a space
    let xAt = 0 // the line's width up to there
    let bold = kind === H
    let run = 0
    let nextRun = runs ? 0 : n + 1
    const any = kind === PRE
    for (let j = 0; j < n; j++) {
      if (j === nextRun) {
        bold = kind === H || (runs![run + 1] & BOLD) !== 0
        run += 2
        nextRun = run < runs!.length ? runs![run] : n + 1
      }
      const c = text.charCodeAt(j)
      if (c === 10) {
        put(r, i, start, j, line)
        start = j + 1
        x = 0
        brk = -1
        continue
      }
      let w = c < 0x180 ? CW[c] : wide(c)
      if (bold) w *= 1.06
      x += w
      if (c === 32) {
        brk = j + 1
        xAt = x
      } else if (x > max && j > start) {
        if (brk > start && !any) {
          put(r, i, start, brk, line)
          start = brk
          x -= xAt
        } else {
          // A word wider than the line (an address, a line of code): cut where it is full.
          put(r, i, start, j, line)
          start = j
          x = w
        }
        brk = -1
      }
    }
    if (start < n || n === 0) put(r, i, start, n, line)
  }
  return r.n > before
}

// How tall the whole page is, the part not set yet guessed from its letters.
export function heightOf(r: Rows): number {
  const d = r.doc
  if (r.next >= d.n) return r.bottom + Math.round(r.look.px * 1.5)
  const left = Math.max(0, d.chars - r.seen)
  const perLine = Math.max(8, (r.look.width / r.look.px) * 1.9)
  const blocks = d.n - r.next
  return r.bottom + Math.round((left / perLine + blocks * 0.6) * lineOf(r.look.px)) + r.look.px * 2
}

// The first row whose bottom is below `y`.
export function rowAt(r: Rows, y: number): number {
  let lo = 0
  let hi = r.n
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (r.y[mid] + r.h[mid] <= y) lo = mid + 1
    else hi = mid
  }
  return lo
}

// The row that shows character `at` of block `block` (set as far as it), or -1.
export function rowOf(r: Rows, block: number, at: number): number {
  // Blocks are set in order: a block's rows are found by its number.
  let lo = 0
  let hi = r.n
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (r.block[mid] < block) lo = mid + 1
    else hi = mid
  }
  if (lo >= r.n) return -1
  while (lo + 1 < r.n && r.block[lo + 1] === r.block[lo] && r.from[lo + 1] <= at) lo++
  return lo
}

// Forgets the rows from block `block` on (a fold opened or closed there).
export function cut(r: Rows, block: number) {
  let lo = 0
  let hi = r.n
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (r.block[mid] < block) lo = mid + 1
    else hi = mid
  }
  if (lo >= r.n) {
    if (r.next > block) r.next = block
    return
  }
  r.bottom = lo ? r.y[lo - 1] + r.h[lo - 1] : Math.round(r.look.px * 0.5)
  r.block.length = r.from.length = r.to.length = r.y.length = r.h.length = r.n = lo
  r.next = block
  let seen = 0
  for (let i = 0; i < block; i++) if (r.doc.kind[i] !== NONE) seen += r.doc.text[i].length
  r.seen = seen
}

