import { get, onEvent, normalize } from './app'
import { FIELD, FOLD, H, IMG, LI, LINK, NONE, P, PRE, ROW, SHIFT, blank, feed, feedPush, finish, idAt, jsonDoc, plain, plainPush, resolve, runsOf, sniff,
  tintsOf, bandOf, light, contrast, type Doc } from './page'
import { SLIM, reader } from './read'
import { cut, heightOf, pictureBox, reach, rowAt, rowOf, rows, widthOf } from './lay'

// Pages as the runtime's slimmer hands them over (docs/html-slim.md): a tag is <name a="v">, white space is one
// space. Hacker News's front page: its header row, a story's two lines, a search form.
const HN = '<html><head><title>Hacker News</title><link rel="alternate" type="application/rss+xml" title="RSS" href="index.rss"></head><body>' +
  '<table><tr><td><b><a href="news">Hacker News</a></b> <a href="newest">new</a></td></tr>' +
  '<tr><td>1.</td><td><a href="https://example.com/story">A story about frames</a> (<a href="from?site=example.com">example.com</a>)</td></tr>' +
  '<tr><td>42 points by <a href="user?id=marius">marius</a> | <a href="item?id=1">12 comments</a></td></tr></table>' +
  '<form action="//hn.algolia.com/">Search: <input type="text" name="q"></form></body></html>'

const STORY = '<html><head><title>A story</title></head><body><nav><ul><li><a href="/">Home</a></li><li><a href="/a">About</a></li>' +
  '<li><a href="/b">Blog</a></li><li><a href="/c">Contact</a></li></ul></nav><main><h1 id="top">A story about frames</h1>' +
  '<p>A page with <a href="/next">a link</a> and words after it.</p><img src="/pictures/frame.jpg" width="640" height="360" alt="A frame on a wall">' +
  '<p id="end">The end.</p></main></body></html>'

// Slimmed markup in pieces as it comes: text cut anywhere, a tag never.
function pieces(html: string, size: number): string[] {
  const out: string[] = []
  for (let at = 0; at < html.length; ) {
    let to = Math.min(html.length, at + size)
    if (to < html.length) {
      const lt = html.lastIndexOf('<', to - 1)
      if (lt > html.lastIndexOf('>', to - 1)) to = lt > at ? lt : html.indexOf('>', to) + 1
    }
    out.push(html.slice(at, to))
    at = to
  }
  return out
}

// The Doc of a page's slimmed markup, read whole or in pieces of `size`.
function read(html: string, size = 0, url = 'https://example.com/page', max?: number): Doc {
  const d = blank(url, max)
  const push = reader(d)
  if (size) for (const piece of pieces(html, size)) push(piece, false)
  push(size ? '' : html, true)
  return finish(d)
}

// Every string in the tree, in order.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false || node === true) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  return node.props ? find(node.props.children, test) : null
}

// What the tree says, its spaces (the no-break ones at a link's edge too) as one.
const said = (tree: any) => texts(tree).join(' ').replace(/[\s ]+/g, ' ')
// The element that says `text` and takes a tap.
const tappable = (tree: any, text: string) =>
  find(tree, (n) => !!n.props && typeof n.props.onClick === 'function' && texts(n).join('').replace(/ /g, ' ').trim() === text)

type Served = { html?: string; text?: string; type?: string; status?: number; url?: string }
let asked: { url: string; init: any }[] = []
const realFetch = (globalThis as any).fetch

// Pages by address, each handed over as a runtime that streams hands a page over: in pieces, inside the call.
function serve(pages: Record<string, Served>, piece = 200) {
  asked = []
  const f: any = (url: string, init: any) => {
    asked.push({ url, init })
    const page = pages[url]
    // No answer at all: the promise rejects (here at once: a test has no later).
    if (!page) return { then: (_: any, no: any) => no(new TypeError('fetch failed: getaddrinfo ENOTFOUND')) }
    return new Promise((ok) => {
      const slimmed = page.html !== undefined && !!init.slim
      const info: any = { status: page.status || 200, url: page.url || url, headers: { 'content-type': page.type || 'text/html' }, done: false,
        bytes: 0, slim: slimmed ? 'html' : '' }
      const body = page.html ?? page.text ?? ''
      let go = true
      // Markup comes with its tags whole; text in any cut.
      for (const part of slimmed ? pieces(body, piece) : body.match(new RegExp(`[^]{1,${piece}}`, 'g')) || []) {
        go = init.onChunk(part, info) !== false
        if (!go) break
      }
      if (go) {
        info.done = true
        init.onChunk('', info)
      }
      ok({ status: info.status, ok: true, url: info.url })
    })
  }
  f.chunks = true
  ;(globalThis as any).fetch = f
}

afterEach(() => {
  ;(globalThis as any).fetch = realFetch
})

const PAGES: Record<string, Served> = {
  'https://news.ycombinator.com/': { html: HN },
  'https://example.com/story': { html: STORY },
}
const show = (app: any) => get(app, makeContext())
// A browser whose home page is Hacker News, its memory empty.
const browser = (home = 'https://news.ycombinator.com/') => makeApp({ state: { homepage: home } })

describe('a page from its slimmed markup', () => {
  it('is its blocks, links, fields and what the page says of itself', () => {
    const d = read(HN, 0, 'https://news.ycombinator.com/')
    expect(d.title).toBe('Hacker News')
    expect(d.feeds).toEqual(['index.rss', 'RSS'])
    expect(d.links.slice(1, 4)).toEqual(['news', 'newest', 'https://example.com/story'])
    expect(d.kind.slice(1)).toEqual([ROW, ROW, ROW, P, FIELD])
    expect(d.text[2]).toBe('1. A story about frames (example.com)')
    expect(runsOf(d, 2)).toEqual([0, 0, 3, 768, 23, 0, 25, 1024, 36, 0])
    expect(d.forms[0]).toEqual({ post: false, action: '//hn.algolia.com/', fields: [0] })
    expect(d.fields[0].name).toBe('q')
    expect(resolve(d.links[4], d.base)).toBe('https://news.ycombinator.com/from?site=example.com')
  })

  it('folds what is around the page, and what comes before its own part', () => {
    const d = read(STORY)
    // The navigation is a fold of its four links; the page's own part starts after it, so all before is one fold.
    expect(d.kind[0]).toBe(FOLD)
    expect(d.folds[d.meta[0] >> SHIFT].label).toBe('Top of the page')
    expect(d.kind[1]).toBe(FOLD)
    const nav = d.folds[d.meta[1] >> SHIFT]
    expect([nav.label, nav.links, nav.end - nav.at - 1]).toEqual(['Navigation', 4, 4])
    expect(idAt(d, 'top')).toBe(6)
    expect(idAt(d, 'nowhere')).toBe(-1)
    expect(d.kind[6]).toBe(H)
    expect(d.kind[8]).toBe(IMG)
    expect(d.imgs[0]).toEqual({ w: 640, h: 360, link: 0, src: '/pictures/frame.jpg', alt: 'A frame on a wall' })
  })

  it('folds a part named for a menu only when it is mostly links', () => {
    const part = (first: string) => read(`<div class="menu"><p>${first}</p><p>x</p><p>y</p></div>`).kind[1]
    expect(part('<a href="/a">one</a> <a href="/b">two</a> <a href="/c">three</a>')).toBe(FOLD)
    expect(part('A long paragraph that only mentions <a href="/a">a</a> <a href="/b">b</a> <a href="/c">c</a> somewhere in its many words')).toBe(NONE)
  })

  it('keeps a <details> as a fold under its summary, open if it was', () => {
    const d = read('<details open=""><summary>More about it</summary><p>one</p><p>two</p><p>three</p></details>')
    const f = d.folds[0]
    expect([d.kind[1], f.label, f.open]).toEqual([FOLD, 'More about it', true])
  })

  it('keeps the colors a page states: a palette, each block\u2019s stretches, its theme', () => {
    const d = read('<meta name="theme-color" content="#ff6600"><table><tr><td bgcolor="#ff6600">Hacker News</td></tr></table>' +
      '<p style="background:#f6f6ef">One <font color="green">green word</font></p><p>Plain</p>')
    expect(d.theme).toBe('#ff6600')
    expect(d.palette).toEqual(['', '#ff6600', '#f6f6ef', '#008000'])
    expect(tintsOf(d, 1)).toEqual([0, 0, 1])
    expect(bandOf(d, 1)).toBe(1)
    expect(tintsOf(d, 2)).toEqual([0, 0, 2, 4, 3, 2])
    expect(bandOf(d, 2)).toBe(0) // two stretches: no one color behind the whole block
    expect(tintsOf(d, 3)).toBe(null)
    expect(light('#ffffff') > 0.99 && light('#000000') < 0.01).toBe(true)
    expect(Math.round(contrast('#000000', '#ffffff'))).toBe(21)
  })

  it('stops at what it keeps', () => {
    const d = blank('https://example.com/', 50)
    const push = reader(d)
    expect(push('<p>' + 'word '.repeat(20) + '</p><p>never kept</p>', false)).toBe(false)
    expect(push('<p>nor this</p>', true)).toBe(false)
    expect(d.cut).toBe(true)
