  })
})

// What the reader makes of markup, a rule a test: the page as the slimmer hands it over, and the Doc as text.
// A Doc as text, the way the rules below are written: a block a line (its kind and place, where its runs start, its
// words; a picture, a field and a fold with what they are), then what the page holds beside its blocks. → is between
// the parts of a line, ⏎ ends one, ␤ is a line break in a text, ␁ follows a list item's mark.
function shown(d: Doc): string {
  const out: string[] = []
  const nl = (s: string) => s.replace(/\n/g, '␤')
  for (let i = 0; i < d.n; i++) {
    const k = d.kind[i]
    const place = d.meta[i] & 255
    const at = d.meta[i] >> 8
    const tints = d.tints[i]
    if (tints !== undefined) out.push('~' + tints)
    if (k === 9) {
      if (i > 0) out.push('.' + place)
    } else if (k === 4) out.push('-' + place)
    else if (k === 5) out.push(`i${place}→${d.imgs[at].w}→${d.imgs[at].h}→${d.imgs[at].link}→${d.imgs[at].src}→${d.imgs[at].alt}`)
    else if (k === 6) {
      const f = d.fields[at]
      out.push(`f${place}→${f.form}→${f.type}→${f.on ? 1 : 0}→${f.name}→${nl(f.value)}→${f.label}` + (f.options ? '→' + f.options.join('→') : ''))
    } else if (k === 7) {
      const f = d.folds[at]
      out.push(`[${place}→${f.label}→${f.end - f.at - 1} blocks→${f.links} links` + (f.open ? '→open' : ''))
    } else out.push('phlr....w'[k] + d.meta[i] + '→' + (d.runs[i] || '') + '→' + (k === 2 ? d.mark[i] + '␁' : '') + nl(d.text[i]))
  }
  if (d.links.length > 1) out.push('A' + d.links.slice(1).join('→'))
  if (d.idNames.length) out.push('#' + d.idNames.map((name, i) => name + '=' + d.idBlocks[i]).join('→'))
  d.forms.forEach((f) => out.push(`F${f.post ? 1 : 0}→${f.action}→${f.fields}`))
  d.fields.forEach((f) => f.type === 'hidden' && out.push(`f→${f.form}→hidden→${f.name}→${f.value}`))
  if (d.title) out.push('T' + d.title)
  if (d.base !== d.url) out.push('B' + d.base)
  if (d.desc) out.push('D' + d.desc)
  if (d.refresh) out.push('R' + d.refresh)
  if (d.feeds.length) out.push('E' + d.feeds.join('→'))
  if (d.theme) out.push('C' + d.theme)
  if (d.palette.length > 1) out.push('K' + d.palette.slice(1).join('→'))
  if (d.cut) out.push('X')
  return out.join('⏎')
}

