      for (let i = 0; i < rss.length; i += size) feedPush(f, rss.slice(i, i + size), i + size >= rss.length)
      expect(d.title).toBe('News')
      expect(d.text.slice(1)).toEqual(['One & only', 'Mon, 23 Nov 2026', 'A bold start.', 'Two'])
      expect(d.links.slice(1)).toEqual(['https://example.com/1', 'https://example.com/2'])
      expect(d.kind[1]).toBe(H)
    }
    const atom = `<feed xmlns="http://www.w3.org/2005/Atom"><title>Releases</title><entry><title>v2</title>
<link rel="alternate" type="text/html" href="https://example.com/v2"/><updated>2026-11-24T08:00:00Z</updated>
<content type="html">&lt;p&gt;Faster.&lt;/p&gt;</content></entry></feed>`
    const d = blank('https://example.com/atom')
    feedPush(feed(d), atom, true)
    expect(d.text.slice(1)).toEqual(['v2', '2026-11-24 08:00', 'Faster.'])
    expect(d.links[1]).toBe('https://example.com/v2')
  })

  it('reads plain text: lines that read on are a paragraph, lines laid out by hand stay', () => {
    const d = blank('https://example.com/a.txt')
    const p = plain(d, false)
    plainPush(p, 'A paragraph of plain text that was wrapped by hand at some\ncolumn, as a mail or an RFC is.\n\n', false)
    plainPush(p, '   +------+------+\n   | left | right|\n   +------+------+\n\nLast line.', true)
    expect(d.kind.slice(1)).toEqual([P, PRE, P])
    expect(d.text[1]).toBe('A paragraph of plain text that was wrapped by hand at some column, as a mail or an RFC is.')
    expect(d.text[2].split('\n').length).toBe(3)
  })

  it('reads Markdown, JSON, and knows which is which', () => {
    const d = blank('https://example.com/README.md')
    plainPush(plain(d, true), '# Title\n\nSome **bold** and a [link](https://example.com/x).\n\n- one\n- two\n\n```\ncode  here\n```\n', true)
    expect(d.kind.slice(1)).toEqual([H, P, LI, LI, PRE])
    expect(d.text[2]).toBe('Some bold and a link.')
    expect(d.links[1]).toBe('https://example.com/x')
    expect(runsOf(d, 2)!.includes(LINK)).toBe(true)
    const j = blank('https://example.com/api')
    jsonDoc(j, '{"a":[1,2]}')
    expect(j.text[1]).toBe('{\n  "a": [\n    1,\n    2\n  ]\n}')
    expect(sniff('<!doctype html><html>', '', 'https://example.com/')).toBe('html')
    expect(sniff('<?xml version="1.0"?><rss version="2.0">', 'text/xml', 'https://example.com/f')).toBe('feed')
    expect(sniff('{"a":1}', 'application/json', 'https://example.com/a')).toBe('json')
    expect(sniff('Plain words.', 'text/plain', 'https://example.com/a.txt')).toBe('text')
    expect(sniff('# Title', 'text/plain', 'https://example.com/README.md')).toBe('markdown')
    expect(sniff('%PDF-1.7', '', 'https://example.com/a')).toBe('pdf')
    expect(sniff('\u0089PNG', 'image/png', 'https://example.com/a')).toBe('image')
  })

  it('reads a link against its page', () => {
    const base = 'https://example.com/a/b/page.html?x=1'
    expect(resolve('next', base)).toBe('https://example.com/a/b/next')
    expect(resolve('../up', base)).toBe('https://example.com/a/up')
    expect(resolve('/root', base)).toBe('https://example.com/root')
    expect(resolve('//cdn.example.net/x.png', base)).toBe('https://cdn.example.net/x.png')
    expect(resolve('?y=2', base)).toBe('https://example.com/a/b/page.html?y=2')
    expect(resolve('#part', base)).toBe('https://example.com/a/b/page.html?x=1#part')
    expect(resolve('javascript:void(0)', base)).toBe('')
    expect(resolve('mailto:a@example.com', base)).toBe('mailto:a@example.com')
  })
})

describe('a page set in lines', () => {
  const long = 'The quick brown fox jumps over the lazy dog and keeps on running through the field. '.repeat(6).trim()
  const page = () => {
    return read(`<h1>A heading</h1><p>${long}</p><p>line one<br>line two</p><pre>first\n  second</pre>` +
      `<p>https://example.com/${'a-very-long-address/'.repeat(12)}</p>`)
  }
  const look = { width: 400, px: 16, pics: true, tall: 200 }

  it('breaks at spaces within the page’s width, at a line break, and inside a word too long for a line', () => {
    const d = page()
    const r = rows(d, look)
    reach(r, 1e9)
    const room = (400 - 16) * 1000
    let para = 0
    for (let i = 0; i < r.n; i++) {
      const b = r.block[i]
      const size = d.kind[b] === H ? 24 : d.kind[b] === PRE ? 14 : 16
      const text = d.text[b].slice(r.from[i], r.to[i]).trimEnd()
      expect(widthOf(text, 0, text.length) * size * (d.kind[b] === H ? 1.06 : 1) <= room).toBe(true)
      if (b === 2) para++
    }
    expect(para > 5).toBe(true)
    const of = (b: number) => r.block.map((x, i) => (x === b ? d.text[b].slice(r.from[i], r.to[i]) : null)).filter((x) => x !== null)
    expect(of(3)).toEqual(['line one', 'line two'])
    expect(of(4)).toEqual(['first', '  second'])
    expect(of(5).length > 2).toBe(true)
    expect(of(5).join('')).toBe(d.text[5])
    // Every letter of a paragraph is in one row.
    expect(of(2).join('')).toBe(long)
  })

  it('sets only as far down as it is asked to', () => {
    let html = ''
    for (let i = 0; i < 400; i++) html += `<p>Paragraph ${i}: ${long}</p>`
    const d = read(html)
    const r = rows(d, look)
    reach(r, 600)
    expect(r.next < 20).toBe(true)
    const guessed = heightOf(r)
    reach(r, 1e9)
    expect(r.next).toBe(d.n)
    // The guess of what was not set yet is within a third of what it comes to.
    expect(Math.abs(guessed - heightOf(r)) < heightOf(r) / 3).toBe(true)
    const row = rowOf(r, 200, 0)
    expect(r.block[row]).toBe(200)
    expect(rowAt(r, r.y[row] + 1)).toBe(row)
  })

  it('skips what a closed fold holds, and sets it once it is opened', () => {
    const d = read(STORY)
    const r = rows(d, look)
    reach(r, 1e9)
    const shown = () => r.block.map((b) => d.text[b] || d.kind[b])
    expect(shown()[0]).toBe(FOLD)
    expect(shown()).not.toContain('Home')
    const top = d.folds[d.meta[0] >> SHIFT]
    top.open = true
    cut(r, 0)
    reach(r, 1e9)
    expect(r.block.filter((b) => d.kind[b] === FOLD).length).toBe(2) // the navigation inside it, still folded
    d.folds[d.meta[1] >> SHIFT].open = true
    cut(r, 1)
    reach(r, 1e9)
    expect(shown()).toContain('Home')
  })

  it('gives a picture its shape within the page', () => {
    expect(pictureBox(640, 360, 400, 300)).toEqual([400, 225])
    expect(pictureBox(100, 400, 400, 300)).toEqual([75, 300])
    expect(pictureBox(0, 0, 400, 300)).toEqual([400, 225])
  })
})

describe('the browser', () => {
  it('reads an address, or searches for words', () => {
    expect(normalize('example.com/a')).toBe('https://example.com/a')
    expect(normalize('http://example.com')).toBe('http://example.com')
    expect(normalize('192.168.1.10:8989/x')).toBe('http://192.168.1.10:8989/x')
    expect(normalize('nim lang')).toBe('https://lite.duckduckgo.com/lite/?q=nim+lang')
    expect(normalize('  ')).toBe('')
  })

  it('opens on its start page: a search, the bookmarks', () => {
    serve({})
    const app = makeApp()
    const words = said(show(app))
    expect(words).toContain('Hacker News')
    expect(asked.length).toBe(0)
    const field = find(show(app), (n) => n.type === 'input' && n.props.placeholder === 'Search the web, or type an address')
    field.props.onChange({ target: { value: 'e-paper frames' } })
    field.props.onKeyDown({ key: 'Enter' })
    show(app)
    expect(asked[0].url).toBe('https://lite.duckduckgo.com/lite/?q=e-paper+frames')
    // A bookmark is a tile in its site's color.
    const tile = tappable(show(makeApp()), 'Hacker Newsnews.ycombinator.com')
    expect(tile.props.className).toContain('bg-[#')
  })

  it('asks for a page as a text browser, in pieces, slimmed by the runtime', () => {
    serve(PAGES)
    const words = said(show(browser()))
    expect(asked[0].url).toBe('https://news.ycombinator.com/')
    expect(asked[0].init.slim).toBe(SLIM)
    expect(asked[0].init.headers['User-Agent']).toContain('Lynx')
    expect(words).toContain('A story about frames')
    expect(words).toContain('42 points by marius | 12 comments')
  })

  it('opens a link when it is tapped, against the page it is on', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), 'A story about frames').props.onClick({})
    const words = said(show(app))
    expect(asked[1].url).toBe('https://example.com/story')
    expect(words).toContain('A page with a link and words after it.')
    expect(words).not.toContain('Contact') // its navigation is folded
    expect(words).toContain('Top of the page')
    tappable(show(app), 'a link').props.onClick({})
    show(app)
    expect(asked[2].url).toBe('https://example.com/next')
  })

  it('goes back at once, to a page it kept, and forward', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), '12 comments').props.onClick({})
    show(app)
    const before = asked.length
    expect(onEvent(app, makeContext({ event: 'back' }))).toBe(true)
    expect(said(show(app))).toContain('42 points')
    expect(asked.length).toBe(before)
    expect(onEvent(app, makeContext({ event: 'back' }))).toBe(false)
    expect(onEvent(app, makeContext({ event: 'forward' }))).toBe(true)
    show(app)
  })

  it('reads a page’s links against where it was sent on to', () => {
    serve({ 'https://example.com/old': { html: '<a href="next">Onwards</a>', url: 'https://www.example.org/new/place' } })
    const app = browser('https://example.com/old')
    tappable(show(app), 'Onwards').props.onClick({})
    show(app)
    expect(asked[1].url).toBe('https://www.example.org/new/next')
  })

  it('opens a fold when its line is tapped', () => {
    serve(PAGES)
    const app = browser('https://example.com/story')
    expect(said(show(app))).not.toContain('Home')
    tappable(show(app), '+Top of the page4 links').props.onClick({})
    tappable(show(app), '+Navigation4 links').props.onClick({})
    expect(said(show(app))).toContain('Home')
  })

  it('draws the lines that show, not the page', () => {
    let html = ''
    for (let i = 0; i < 2000; i++) html += `<p>Paragraph number ${i} of a very long page.</p>`
    serve({ 'https://example.com/long': { html } })
    const words = said(show(browser('https://example.com/long')))
    expect(words).toContain('Paragraph number 0 ')
    expect(words).not.toContain('Paragraph number 60 ')
  })

  it('sends a form: its fields in the address, or posted', () => {
    const form = (post: number) => `<form action="/search"${post ? ' method="post"' : ''}><input name="q" placeholder="Words">` +
      '<input type="hidden" name="lang" value="en"><button name="go" value="1">Search</button></form>'
    serve({ 'https://example.com/': { html: form(0) }, 'https://example.com/post': { html: form(1) } })
    let app = browser('https://example.com/')
    find(show(app), (n) => n.type === 'input' && n.props.placeholder === 'Words').props.onChange({ target: { value: 'nim lang' } })
    tappable(show(app), 'Search').props.onClick({})
    show(app)
    expect(asked[1].url).toBe('https://example.com/search?q=nim+lang&lang=en&go=1')
    app = browser('https://example.com/post')
    find(show(app), (n) => n.type === 'input' && n.props.placeholder === 'Words').props.onChange({ target: { value: 'a&b' } })
    tappable(show(app), 'Search').props.onClick({})
    show(app)
    const sent = asked[asked.length - 1]
    expect([sent.url, sent.init.method, sent.init.body]).toEqual(['https://example.com/search', 'POST', 'q=a%26b&lang=en&go=1'])
  })

  it('shows text, a feed and JSON that came as they are', () => {
    serve({
      'https://example.com/a.txt': { text: 'Plain words\nthat read on.\n', type: 'text/plain' },
      'https://example.com/feed': { text: '<rss><channel><title>F</title><item><title>Entry one</title><link>https://example.com/1</link></item></channel></rss>', type: 'application/rss+xml' },
      'https://example.com/api': { text: '{"frames":2}', type: 'application/json' },
    }, 9)
    expect(said(show(browser('https://example.com/a.txt')))).toContain('Plain words that read on.')
    expect(said(show(browser('https://example.com/feed')))).toContain('Entry one')
    expect(said(show(browser('https://example.com/api')))).toContain('"frames": 2')
  })

  it('says why a page did not come, and offers its archived copy', () => {
    serve({})
    const app = browser('https://nowhere.example/')
    const tree = show(app)
    expect(said(tree)).toContain('This page did not load')
    expect(said(tree)).toContain('ENOTFOUND')
    tappable(tree, 'Archived copy').props.onClick({})
    show(app)
    expect(asked[asked.length - 1].url).toBe('https://web.archive.org/web/2id_/https://nowhere.example/')
  })

  it('says so when a site wants scripts', () => {
    serve({ 'https://walled.example/': { html: '<title>Just a moment...</title><p>Enable JavaScript and cookies to continue</p>', status: 403 } })
    expect(said(show(browser('https://walled.example/')))).toContain('asks for a script-running browser')
  })

  it('shows a link’s card when it is held, with its QR code', () => {
    serve(PAGES)
    const app = browser()
    const link = tappable(show(app), 'A story about frames')
    link.props.onLongPress({})
    const tree = show(app)
    expect(said(tree)).toContain('https://example.com/story')
    expect(find(tree, (n) => n.type === 'a' && n.props.href === 'https://example.com/story')).toBeTruthy()
  })

  it('keeps bookmarks on the frame', () => {
    serve(PAGES)
    const app = browser('https://example.com/story')
    show(app)
    const menu = find(show(app), (n) => !!n.props && typeof n.props.onClick === 'function' && find(n, (m) => m.type === 'path' && String(m.props.d).startsWith('M3,6H21')))
    menu.props.onClick({})
    tappable(show(app), 'Bookmark this page').props.onClick({})
    const kept = app.state.marks
    expect(kept[0]).toEqual(['A story', 'https://example.com/story'])
  })

  it('draws a page\u2019s colors: a band behind a row, text that reads on it, the toolbar in the site\u2019s color', () => {
    serve({ 'https://example.com/hn': { html: '<meta name="theme-color" content="#ff6600"><table><tr><td bgcolor="#ff6600"><a href="news">Hacker News</a></td></tr></table>' +
      '<p>Plain <font color="navy" style="background:yellow">yellow</font></p>' } })
    const tree = show(browser('https://example.com/hn'))
    const has = (cls: string) => !!find(tree, (n) => !!n.props && typeof n.props.className === 'string' && n.props.className.includes(cls))
    expect(has('w-full h-[') && has('bg-[#ff6600]')).toBe(true) // the band, and the toolbar
    const link = tappable(tree, 'Hacker News')
    expect(link.props.className).toContain('border-b') // blue would not read on orange: the text's color, underlined
    const word = find(tree, (n) => !!n.props && texts(n).join('') === 'yellow')
    expect(word.props.className).toContain('bg-[#ffff00]')
    expect(word.props.className).toContain('text-[#000080]')
  })

  it('shows a link gone to in another color', () => {
    serve(PAGES)
    const app = browser()
    tappable(show(app), 'A story about frames').props.onClick({})
    show(app)
    onEvent(app, makeContext({ event: 'back' }))
    expect(tappable(show(app), 'A story about frames').props.className).toContain('#6b2fa0')
    expect(tappable(show(app), '12 comments').props.className).toContain('#0b57d0')
  })

  it('shows a picture’s words where pictures are off', () => {
    serve(PAGES)
    const app = browser('https://example.com/story')
    expect(find(show(app), (n) => n.type === 'img' && String(n.props.src).endsWith('/pictures/frame.jpg'))).toBeTruthy()
    frameos.remember('pics', 0)
    expect(said(show(app))).toContain('[A frame on a wall]')
  })
})
